/* @lc app=leetcode id=2827 lang=kotlin */
class Solution { fun numberOfBeautifulIntegers(low: Int, high: Int, k: Int): Int = { s: String -> mutableMapOf<Long, Int>().let { memo -> DeepRecursiveFunction<Long, Int> { state -> memo.getOrPut(state) { (state shr 40).toInt().let { i -> if (i == s.length) (if ((state shr 10 and 31L) == 10L && (state and 1023L) == 0L) 1 else 0) else (state shr 38 and 1L).toInt().let { tight -> (state shr 37 and 1L).toInt().let { lead -> (0..(if (tight == 1) s[i] - '0' else 9)).sumOf { d -> callRecursive((i + 1).toLong() shl 40 or (if (tight == 1 && d == (s[i] - '0')) 1L else 0L) shl 38 or (if (lead == 1 && d == 0) 1L else 0L) shl 37 or (if (lead == 1 && d == 0) 10L else (state shr 10 and 31L) + (if (d % 2 == 0) 1 else -1)) shl 10 or (if (lead == 1 && d == 0) 0L else (state and 1023L) * 10 + d) % k) } } } } } }.invoke(0L shl 40 or 1L shl 38 or 1L shl 37 or 10L shl 10 or 0L) } } }.let { solve -> solve(high.toString()) - solve((low - 1).toString()) } }